quests[11719] = { id = 11719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Test Subject", description = "<Laurith looks you over as if to size you up.>\n\nSo we've got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What's the worst that could happen anyway?\n\nDon't you worry, {name}! Just take this sample and rub it all over your face.", progress = "Don't be afraid.", completion = "Primal Mighthorn will be delighted! This is better than even I expected!\n\nPerhaps it's time that I told you the truth.", objectives = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra has asked that you use the Pollinated Bloodspore Flower and allow her to observe the results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11720] = { id = 11720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Invasion of Gammoth", description = "Hellscream assigned Mighthorn and I with the daunting task of magnataur extermination on the southern front of Warsong Hold. With us came an entire platoon of seasoned Horde soldiers. Our initial foray into the nearby magnataur dens proved quite unsuccessful as our entire squad was wiped out by the lair defenders. We're the only ones left...\n\nWe aren't scientists or researchers. We're soldiers of the Horde, just like you. Soldiers on a mission that cannot fail...\n\nSpeak to Primal Mighthorn now.", completion = "The bloodspore that you collected might just be enough to give us an edge against the magnataurs of Gammoth - with your help, of course.", objectives = "Speak to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11721] = { id = 11721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammothra the Tormentor", description = "Magnataur live in prides, much like lions: one or two dominant males and several females along with their offspring. In the case of Gammoth, the magnataur den west of here, Gammothra is the leader. It is Gammothra that controls this magnataur population and therefore it is Gammothra that must be slain to prevent any type of magnataur uprising.\n\nTake this pouch of crushed bloodspore flower to Gammoth. Use the powder from the pouch to weaken Gammothra and then slay him! Return his head to me as proof.", progress = "The powder can be used to weaken all magnataur. It is why the rat men of the area guard it so closely.", completion = "A job well done, {name}! Would you honor Laurith and I by taking the head of the beast and presenting it to Hellscream? He will be extremely pleased.", objectives = "Slay Gammothra and return the Head of Gammothra to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11722] = { id = 11722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophies of Gammoth", description = "We cannot take all of the credit for this Horde victory, {name}. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra.\n\nHonor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.", progress = "Back so soon?", completion = "<Hellscream picks up the head of Gammothra with one arm and spits in its face.>\n\nThey will learn, {name}... They will all learn. The Horde is not to be trifled with...", objectives = "Take the Head of Gammothra to Garrosh Hellscream in Warsong Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11723] = { id = 11723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deploy the Shake-n-Quake!", description = "Behold, the machine that will save us from the Nerubian threat!\n\n<Abner beams with pride as he presents the finished bot.>\n\nTake this remote control with you, and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the remote to activate the Shake-n-Quake 5000. It will do the rest on its own.\n\nDon't be surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, it would be a great opportunity to finish off the Nerubian offensive.", completion = "<Abner listens eagerly as you report your success and the success of the Shake-n-Quake 5000.>\n\nFizzcrank will be delighted to hear the news! And who knows, perhaps we'll make a mechanic of you yet!", objectives = "Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Shake-n-Quake 5000 to collapse the Nerubian tunnels and defeat Lord Kryxix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11724] = { id = 11724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massive Moth Omelet?", description = "This egg was obviously important to somebody, as the corpse nearby can attest. As you look the egg over you notice that it has already been tagged for shipment to the Bloodspore Plains, care of Bloodmage Laurith. That's just east of here!\n\nCollect the egg and take it to the expectant Bloodmage.", progress = "Greetings!", completion = "Alkor is no more, eh? A pity... As for the egg, we have no real use for it anymore. We've got much bigger problems to deal with now.", objectives = "Take the Massive Glowing Egg to Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11725] = { id = 11725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Pilot Tailspin", description = "I should've flown the mission myself. It's not that I don't trust Tailspin. Far from it. Heck, he was the best wingman I ever flew with.\n\nNo, it's just that it's my responsibility to lead a mission of such import.\n\nI sent Tailspin out with our fastest recon squadron to gather information about the Nerubian infestation in the middle of the Geyser Fields.\n\nThe last report we received placed his squadron in the pools to the far south and just west of the Nerubian sinkholes.\n\nFind Tailspin, {name}.", completion = "Thank goodness. It was terrible.\n\nThere was a bright flash on the ground, and then, the next thing I know, the squadron's going down! I'm hurt pretty badly, so I haven't had a chance to comb the site for other survivors, but something tells me I don't think there will be many.\n\n<Iggy grimaces in pain.>\n\nWill you help me complete my mission?", objectives = "Locate Iggy \"Tailspin\" Cogtoggle in the Geyser Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11726] = { id = 11726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Bit of Spice", description = "The wolves have been pawing through the wreckage ever since the crash and I'm afraid they consumed the microfilm from our mission in the process.\n\nI have a plan to recover that microfilm, but I need your help to make it work.\n\nTo the south and east, in the Flood Plains, live creatures called gorlocs. They prepare their foods with noxious spices, which would sicken any other creature. If you can gather enough of the spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.", progress = "Do you have those spice pouches?", completion = "<Iggy holds his nose as he empties the spice pouches and addresses you in a nasal voice.>\n\nNow that we have what we need, I'll combine it with my emergency rations to create a bait for the wolves.", objectives = "Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to gather 4 Gorloc Spice Pouches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11727] = { id = 11727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time for Heroes", description = "It's good to have you among us, {name}.  We've all heard of your past deeds.\n\nAs you know, King Wrynn is moving great armies into Northrend to meet those of Arthas.  But armies are nothing without true heroes to inspire and lead them.\n\nI want you to be that hero for my men.  Fight alongside them against the Scourge that lays siege to our stronghold.\n\nReport to Sergeant Hammerhill outside the inner hold.  Valiance Keep cannot fall.  The future of our campaign depends on it.", completion = "By Magni's beard!  Looks like the heavy artillery's arriving.", objectives = "Report to Sergeant Hammerhill at Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11728] = { id = 11728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupus Pupus", description = "Whatever you do, don't eat this bait yourself. Just set it down in the vicinity of an oil-soaked wolf. If they're desperate enough to eat the microfilm, they'll come running when they smell the bait.\n\nSimply wait for nature to take its course and then all you need to do is search the, uh... byproduct for the film.\n\nI'd offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. I'm afraid you'll have to conduct the... err... search the old-fashioned way.", progress = "Have you recovered the microfilm?", completion = "<Iggy holds his nose as he accepts the microfilm from you.>\n\nYuck, well, we've complied with section 8.2, paragraph B of the emergency protocol here and recovered the film. Nothing in the protocol says I'm responsible for cleaning it, though.", objectives = "Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to bring him 8 pieces of Microfilm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11729] = { id = 11729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultrasonic Screwdriver", description = "The unit you just dismantled had this inside of its mechanical innards.\n\nIt looks pretty complicated... certainly someone back at the airstrip would want to take a look at it. Maybe Crafty Wobblesprocket?", progress = "Hey!", completion = "My screwdriver... you found my screwdriver! I'd been wondering where that thing got lost.\n\nHmm, you found it inside one of their robots, you say? That gives me an idea....", objectives = "Deliver the Ultrasonic Screwdriver to Crafty Wobblesprocket at Fizzcrank Airstrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11730] = { id = 11730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master and Servant", description = "The Ultrasonic Screwdriver is the ultimate tool. It can do anything to mechanical stuff!\n\nHead back into the pools and dismantle a number of Mechazod's robots. Then all you have to do is use the screwdriver on their remains, and I'm betting that they'll turn to our side, for a short time anyway.\n\nI'm pretty sure it won't work on the mechagnomes, so don't even bother with them.\n\nOh, and if you want to take anything from the robot's insides, you'll want to do so before using the screwdriver!", completion = "Woo hoo! And you brought back the screwdriver intact, too!\n\nReprogramming those robots is going to turn out to be a huge advantage in our favor in the fight against Gearmaster Mechazod. I think you've earned a little something for that.", objectives = "Use the Ultrasonic Screwdriver to reprogram 15 robots and then return to Crafty Wobblesprocket at Fizzcrank Airstrip.\n\nMake sure to loot the dead robot before you reprogram it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11731] = { id = 11731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lesson.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", objectives = "Win the torch tossing game, then speak with the Master Fire Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11732] = { id = 11732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", progress = "Desecrate the Horde's Arathi Highlands bonfire!", completion = "Desecrate the Alliance's Arathi Highlands bonfire!" }
quests[11733] = { id = 11733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traversing the Rift", description = "I've been mindful of your efforts, mortal. Do not feign surprise. Surely you've felt my eye upon you.\n\nThe time has come to peel back a layer of darkness from your mind. There are stark truths that you have grown ready to accept.\n\nBefore hearing the tale, you shall be shown firsthand what we face.\n\nPut your affairs in order, {class}....", completion = "Welcome to Coldarra, {class}.\n\nUnder the Transitus Shield we lie hidden just a stone's throw from the Nexus, fortress of the great aspect Malygos and his blue dragonflight.\n\nDo make yourself comfortable.", objectives = "Surristrasz wants you to travel to Coldarra. Once there, you are to speak with Archmage Berinand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11734] = { id = 11734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", objectives = "Desecrate the Alliance's Ashenvale bonfire!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
