quests[11863] = { id = 11863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Zangarmarsh flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11864] = { id = 11864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mission Statement", objectives = "The demon has many names and each name has held special meaning at one time or another. While the details were sometimes insignificant, the end result was always the same: death.\n\nBut it is now, nearly fifty years after it all began, that the details will find the devil and lead to his downfall.\n\nThis time, we have him... There will be no escape for Nesingwary.\n\nNorthrend will be the battleground for our war. The hunter will become the hunted!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11865] = { id = 11865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfit for Death", description = "Just south of us the caribou used to roam freely, peacefully. Then Nesingwary showed up and everything changed. Now the caribou are in a perpetual state of frenzy, always in a panic. They are stalked by the hunters and trappers hidden in the field.\n\nNesingwary's executioners are unfit for death. They must feel the torture that they put the caribou through!\n\nTake this pile of fake furs and lay it upon their caribou traps to the south. Watch as the hunters are caught in their own deadly traps!", completion = "You do the Earth Mother's work, {name}, but do not revel in this victory for too long. We have discovered the hiding place of the trapper leader.", objectives = "Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the Pile of Fake Furs to trap 8 Nesingwary Trappers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11866] = { id = 11866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears of Our Enemies", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", progress = "Ears will do quite nicely...", completion = "These will hang around my neck. Let them hear our message and let these ears be the vessels that carry our truths!", objectives = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11867] = { id = 11867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Get Ear-nough...", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and does dare strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", progress = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", completion = "These will hang around my neck. Let them hear our message and let these ears be the vessels that carry our truths!", objectives = "Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11868] = { id = 11868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Culler Cometh", description = "Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons!\n\nFind this murderer, Karen, and end her worthless existence.\n\nPrepare yourself properly, {name}. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her!", completion = "Perhaps her death will serve as an example to others that dare slay animals for sport and riches.", objectives = "Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Karen the Culler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11869] = { id = 11869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Happy as a Clam", description = "To the west of us you will find Lake Kum'uya. It is, as far as we know, the only freshwater giant clam habitat in the world.\n\nOf course Nesingwary's lackeys are now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught to those that would think to endanger an entire species.\n\nGo to Lake Kum'uya and locate the loot crazed divers. Slay them until the water runs red! Return to me when a proper example has been made!", progress = "It is gruesome work that we do, {name}.", completion = "Now let us see how their nerve holds up when they see what became of their companions!", objectives = "Hierophant Cenius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill 10 Loot Crazed Divers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11870] = { id = 11870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abandoned Reach", description = "We have just gotten word from Liandra that mercenaries hired by Nesingwary are moving goods off the beach and onto the main Nesingwary shipping vessel. No doubt they plan on making a fortune from their murderous trade!\n\nShe has asked that we send assistance to the Abandoned Reach, directly south of here on the beachfront of the Borean Tundra.\n\nMake haste, Liandra awaits you there!", completion = "Cenius sent you? Well you're not a moment too soon!", objectives = "Seek out Hierophant Liandra at the Abandoned Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11871] = { id = 11871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not On Our Watch", description = "Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks of animal parts. It would seem that Nesingwary is in cahoots with the Northsea Freebooters. Those dirty pirates are transporting the goods that Nesingwary's murderous lackeys gather offshore. No doubt they will end up in the homes and on the backs of wealthy, unscrupulous individuals across Azeroth.\n\nThis won't happen. Not on our watch. Bring me all shipments that you find upon this beach. They'll never have them!", progress = "We will give those animals a proper burial.", completion = "A job well done, {name}. Now we strike at the pirate leader!", objectives = "Hierophant Liandra at the Abandoned Reach in the Borean Tundra wants you to recover 12 Shipments of Animal Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11872] = { id = 11872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nefarious Clam Master...", description = "It's despicable, really, to anoint one's self as the \"Clam Master,\" as if they hold mastery over the creatures of the sea. None may make such claims!\n\nThis \"Clam Master\" must be found and slain. He was last seen at the wreckage just off the coast of the Abandoned Reach. Find him and kill him.\n\nOnce this is done, return to Hierophant Cenius at the D.E.H.T.A. Encampment, north of here, and let her know that the mission was a success.", completion = "Excellent work, {name}. We are closing in on Nesingwary!", objectives = "Slay Clam Master K and return to Hierophant Cenius at the D.E.H.T.A. Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11873] = { id = 11873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Fizzcrank the News", description = "Would you be willing to head back to the airstrip and let Fizzcrank know that I'll be along shortly to give my formal report? I've got to deal with the wreckage of my flying machine, and then I'll be on my way.\n\nI'll be certain that Fizzcrank knows that he has you to thank for my survival and the recovery effort.\n\nI only wonder what the old man would've done himself if he'd been flying with us. I miss those days.", completion = "<Fizzcrank listens to your report, looking somewhat relieved.>\n\nI should've gone with them. We might've been able to complete the mission without losing any pilots.\n\nTailspin is right, though, we have you to thank for what you've been able to salvage. Your efforts may just make the difference in the fight against the Nerubians.", objectives = "Make your way back to Fizzcrank Airstrip and speak with Fizzcrank Fullthrottle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11874] = { id = 11874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upper Deck Promo - Rocket Mount" }
quests[11875] = { id = 11875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining the Advantage", description = "The troops of the Shattered Sun Offensive will need every advantage they can get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils which will strengthen the blades and armor of our troops.\n\nThe key ingredient, nether residue, pervades Outland  -- if you know where to look. Any master herbalist, skinner, or miner who knows the signs can gather it while plying <his/her> trade. Those herbs, ores, and beasts native to Outland may all bear the residue.", progress = "Have you any residue for me?", completion = "Thank you for your help, {name}. No contribution to the war effort is too small. Our men are going to need every advantage they can get in this battle.", objectives = "Bring 8 Nether Residue to Emissary Mordin in Shattrath City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11876] = { id = 11876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Those That Cannot Help Themselves", description = "They're majestic beasts, aren't they?\n\n<Lathorius points towards the mammoths of the northern tundra.>\n\nWith each passing day their numbers diminish. Demons that call themselves hunters slay the beasts for sport and riches.\n\n<Lathorius' face contorts with anger.>\n\nIt's the whimpers that drive me to madness, {name}. You can hear them, carried by the wind. The mammoth calves, trapped in the hunters' vile traps, call out to us.\n\nTake this hammer and smash those traps. Free the calves!", completion = "<Arch Druid Lathorius wipes away his tears.>\n\nThey never stood a chance. Now orphaned, they will surely die on their own.", objectives = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the D.E.H.T.A. Trap Smasher to free 8 Mammoth Calves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11877] = { id = 11877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunfury Attack Plans", description = "As we press the offensive on Quel'Danas, we've discovered that Kael'thas' minions are planning a counterattack. By ordering the Sunfury blood elves, based in Netherstorm, to attack our operations in Outland, he hopes to draw troops and attention away from the Sunwell.\n\nWe must not allow this to happen, {name}. Each and every blade is needed on the front lines.\n\nGo to Netherstorm and capture their attack plans. Any of the Sunfury blood elves up there could be in possession of the plans. Good luck, {name}.", progress = "Have you returned with the plans?", completion = "<Lord Torvos accepts the plans and looks over them.>\n\nYou've done the offensive a great service, {name}, but we should not rest. I wouldn't put it beyond our foes to plan more mischief in the future.", objectives = "Lord Torvos in Shattrath wants you to capture the Sunfury Attack Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11878] = { id = 11878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khu'nok Will Know", description = "Although you have acted valiantly in freeing the trapped calves, many of them will still die. You see, without a caretaker, these calves must fend for themselves in the wild.\n\nBut there is a way! Hope yet remains!\n\nNorth of here in the mammoth fields, bordering the Scalding Pools, you will find Khu'nok the Behemoth: a mammoth as wise as he is ancient. Take this mammoth orphan and present it to Khu'nok. He will know what to do.", completion = "<You hear a voice in your head. It is Khu'nok.>\n\nYour name has been heard in the whistling winds, {name}. You have done a great thing for my kin. For this we will consider you an ally. Alas, our torment cannot end without bloodshed and violence.\n\nThe price of peace for the mammoths will be the death of Kaw...", objectives = "Take the Orphaned Mammoth Calf to Khu'nok the Behemoth in the Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11879] = { id = 11879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaw the Mammoth Destroyer", description = "You cannot defeat the being responsible for the slaughter of my kind by yourself. The mammoths of the tundra will help you!\n\nVenture forth to the plains and find a mammoth bull. He will allow you to mount him and control his movements and actions. Ride upon his back and find Kaw, north of here at Kaw's Roost. Together, you will be the instrument of Kaw's demise.\n\nDestroy Kaw's armies and take from Kaw his coveted war halberd. Return to Lathorius at the D.E.H.T.A. Encampment should you succeed.", progress = "What happened?", completion = "<Lathorius takes the halberd from you.>\n\nIs this what I think it is?\n\n<Lathorius grins.>\n\nSmashing! Outstanding! Another of Nesingwary's lackeys brought to justice!", objectives = "Kill Kaw the Mammoth Destroyer and recover Kaw's War Halberd. Deliver Kaw's War Halberd to Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11880] = { id = 11880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Multiphase Survey", description = "I'm sure that 'gnomish inventor' is a crackpot. He was babbling about some dark distortions that have begun to appear in the Spirit Fields around Oshu'gun in Nagrand.\n\nAccording to him, these, uh, multiphase... um, spectro-goggles will allow the wearer to see the distortions and take readings from them. He insisted that recording this data was fundamental to our campaign at the Sunwell. I think he's nuts, but I'm under orders to investigate anything that might help. Would you mind taking some readings?", progress = "Did you get those readings? That gnome will scream at me again if I don't get his precious data.", completion = "Thanks for your help. You don't know what it's like to have to deal with \"Doctor\" Wafflefry over there. In between his \"checkups\" on my progress, he's busy hawking some gadget or another derived from his military inventions.", objectives = "Harbinger Haronem in Shattrath City wants you to use the Multiphase Spectrographic Goggles to take 6 Multiphase Readings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11881] = { id = 11881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Load'er Up!", description = "Have you seen the flying machines buzzing around? That's gnomish innovation at its finest.\n\nI've long waited to get my hands on some of their technology and a perfect opportunity has presented itself. One of their recon wings crashed in the Scalding Pools, in the southwest part of the Geyser Fields.\n\nBlow this whistle near one of the crashed machines and my trusty mule, Jenny will answer. She'll follow you and carry the salvage, but you must keep her safe. She'll begin to drop the cargo if attacked.", progress = "Don't fail! I'm counting on you.", completion = "<Fezzix looks over the salvage.>\n\nJenny's a little roughed up, but she'll be fine. As for the salvage, it's a bit more... piecemeal than I had hoped, but I should be able to find a use for it. You're not off the hook yet, though. We're going to rebuild this baby.", objectives = "Help Jenny make her way from the crash site to Fezzix Geartwist at Taunka'le Village without losing all her cargo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11882] = { id = 11882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Fire Eater at any Alliance capital. They should be able to help you.", completion = "Well met. You've come to learn some new ways to handle fire?", objectives = "Speak to a Master Fire Eater in any Alliance capital.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11883] = { id = 11883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Dancing?", description = "You wish the learn the art of fire dancing?\n\nWell, then. Speak to a Master Fire Dancer at any Horde capital. They should be able to help you.", sourceObjective = "Speak to a Master Fire Dancer in any Horde capital.", sourceObjectiveStatus = "unverified-source-field" }
quests[11884] = { id = 11884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nedar, Lord of Rhinos...", description = "West of here, on the high bluffs above Lake Kum'uya, roams a despicable being known as Nedar. The self proclaimed \"Lord of Rhinos\" hunts the wastes for the injured or young - rhinos unable to defend themselves against his cowardly attacks. To add insult to injury, Nedar has raised a rhino of his own to become his mount and bodyguard.\n\nIt is a rare thing that D.E.H.T.A. would ever call for the death of an animal, but Nedar's tainted rhino must be disposed of... Kill them both and return to me.", completion = "At least for now the rhinos will know peace. Thank you, {name}.", objectives = "Killinger the Den Watcher at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Nedar, Lord of Rhinos and his companion, \"Lunchbox.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11885] = { id = 11885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  These are powerful beings you will be facing; you would do well to bring friends.", progress = "Have you completed your task, {name}?", completion = "Excellent!  Take this.  I've prepared this bundle with items symbolizing the foes you've defeated.  They will allow you to summon Terokk.\n\nBeware, {name}.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!", objectives = "Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile. Return to Hazzik at Blackwind Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11886] = { id = 11886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Activity", description = "While celebration has its place, {class}, some of us must look to graver matters.\n\nWhen the festival began, we received reports from Zoram Strand about a sharp increase in Twilight Cult activity. The origins of this holiday are steeped in the very powers those madmen revere; this cannot be coincidence. Go to the camp just south of the Blackfathom Deeps entrance, in the ruins, and see if the cultists will part with information - forcefully if need be. Use this beacon to summon a guide when you find it.", progress = "What have you uncovered?", completion = "This is worrisome, friend. It hints at a much larger plot beyond simple agitation of the local fire and water elements, and something here bears investigation...", objectives = "Go to the new Twilight Camp south of the Blackfathom Deeps entrance on the Zoram Strand of Ashenvale and retrieve Twilight Correspondence from the cultists, then call upon the Earthen Ring Guide using the Totemic Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11887] = { id = 11887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Supplies", description = "Rifling through the dead gnome's possessions, you come across a small packet filled with rations, tools, and a handy roll of gnomish duct tape. The contents of these kits might prove helpful to Fezzix Geartwist when it comes time for him to reassemble the wreckage of the gnomish flying machines.\n\nBringing a few of these kits to Fezzix might just be worth a nice bonus.", progress = "What is it you have there?", completion = "Gnomish tools? For me? These should make rebuilding that flying machine even easier than I expected.", objectives = "Collect 7 Gnomish Emergency Toolkits from the bodies of crashed Fizzcrank Recon Pilots and bring them to Fezzix Geartwist at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11888] = { id = 11888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride to Taunka'le Village", description = "{race}, the chieftain is making me wait... time that Taunka'le does not have!\n\nThere has been talk of your prowess. Rather than wait for Garrosh to send help, I ask you to go and help my people.\n\nTaunka'le village lies far to the northeast. Follow the road east out of the hold, turning north at the intersection. Not long after, you will come to another intersection. Follow the path east, passing south and then east of the great pools along the flood plains.\n\nSpeak with Sage Earth and Sky when you arrive.", completion = "It does not surprise me that the orc chieftain does not have time to hear of our troubles. The ambassador's efforts will likely be like so much mist blowing in the wind.\n\nBut you are here now. We shall see if he chose well in sending you.", objectives = "Speak with Sage Earth and Sky at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11889] = { id = 11889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death From Above", description = "We're doing a good job of holding the front lines against these bugs.  Some of these cheeky fiends, however, can fly over the aforementioned front lines and are really beating down on our inner defenses.\n\nI've requisitioned reinforced fishing nets from our civilian ships.  If you've got a good enough throwing arm, they'll help you knock the enemy out of the sky.  Thin their numbers so that our defenses can hold the keep.", completion = "We'll beat them if they come by land and we'll beat them if they come by air.  If these motherless undead come by sea we're going to give them the beating of their lives.", objectives = "Sergeant Hammerhill wants you to use the Reinforced Net to help you slay 6 Scourged Flamespitters outside of Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11890] = { id = 11890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Are They Up To?", description = "The gnomes have run into some trouble in the pools to the west. It serves them right as they have been fouling up the land with their so-called inventions.\n\nI want you to go out to their pumping station and observe what has befallen them. Return to me after.", progress = "What did you find out, {race}?", completion = "Troubling news indeed.\n\nMy people are leaving this place soon. We are going to break through the Scourge lines to get to our capital, Icemist, in the Dragonblight.\n\nBut, before we do that, we must deal with what the gnomes in their insanity have wrought.", objectives = "Investigate the area surrounding the Fizzcrank Pumping Station. Then, return to Sage Earth and Sky at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11891] = { id = 11891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Innocent Disguise", description = "According to this, it seems there is another encampment of the cultists to the northwest of the large gathering on the Zoram Strand, and they are speaking with... guests?\n\nMuch could be learned from listening to these proceedings, {race}. Take this orb; it will allow you to appear as one of the native crawlers on the beach. Spy on the conversation with these \"guests\" of the cultists at the northwestern camp and report back to me when you are successful.", progress = "Have you learned their secrets?", completion = "They seek to summon a frost lord into our world? No! They cannot tip the balance!", objectives = "Use the Orb of the Crawler to spy upon the new Twilight camp to the west of the Blackfathom Deeps entrance on the Zoram Strand in Ashenvale, then summon the Earthen Ring Guide using the Totemic Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11892] = { id = 11892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assassination of Harold Lane", description = "You have done much for the animals of the Borean Tundra, {name}. Nesingwary's lackeys have been beaten back and taught a lesson that they will not soon forget.\n\nHarold Lane, the primary agent responsible for the mass slaughters in Nagrand, has been identified as the man in charge of Nesingwary operations in the tundra. He is stationed at Lake Kum'uya, west of here.\n\n<Lathorius hands you an intricately carved oak horn.>\n\nFind Lane and kill him. Use this horn should you require our aid.", completion = "Alas, Nesingwary is gone. Perhaps he was never here to begin with...\n\n<Lathorius sighs.>\n\nThe demon is a slippery one, but his days are numbered. We will find him and when we do...", objectives = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Harold Lane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11893] = { id = 11893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of the Elements", description = "I kept trying to tell that silly goblin his machines are unreliable.\n\nBut the power of the elements; that is deep and abiding. When my apprenticeship is over, I will wield their full power. What I know now should be sufficient to help out our friend Fezzix, though.\n\nTake this windsoul totem and plant it near any of the steam ragers to the west of the village. The totem will gather up the energies of slain elementals. Return the fully charged totem to me and I'll do the rest.", completion = "<Dorain nods.>\n\nGood. This should be sufficient to show Fezzix exactly what I've been trying to tell him.", objectives = "Dorain Frosthoof at Taunka'le Village wants you to use the Windsoul Totem to gather the energy of 10 Steam Ragers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11894] = { id = 11894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patching Up", description = "Remember all that gnomish duct tape you brought me?\n\nWell, I've found a use for it. The body of this flying machine is so banged up in places, that I'm going to need to reinforce it if I ever hope to fly.\n\nDorain over there has been telling me that the taunka use steam cured caribou leather for making watertight containers. Marsh caribou live all around the village and in the Flood Plains to the south. Get the best hides you can find and cure them over the steam vents in the Geyser Fields.", progress = "Did you get that cured caribou hide for me?", completion = "Fantastic! A few more tweaks and I'll be an airborne goblin!", objectives = "Fezzix Geartwist at Taunka'le Village wants you to bring him 5 Steam Cured Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11895] = { id = 11895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master the Storm", description = "From what you describe, the creatures of metal should be easy to deal with. But first, you must master the storm.\n\nBehind me in the lodge is a totem. When you are ready, focus your will upon it and the storm will come. You must defeat the storm and in so doing take its essence into yourself.\n\nIf others are there, it is enough that you all work together to defeat it. Return to me after, {class}.", progress = "Have you mastered the storm yet?", completion = "I feel the power of the storm coursing through you!\n\nYou are ready, {name}. Let us begin.", objectives = "Defeat the Storm Tempest and then return to Sage Earth and Sky at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11896] = { id = 11896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weakness to Lightning", description = "You now have the power of the storm within you. I will give you the means to focus that power and weaken the robots in the pools.\n\nTake this lightning rod. Use it against the robotic creations of the mechagnomes you find within the greater pools area to the west. Do not worry about using it against the mechagnomes themselves; Greatmother Taiga has other plans for them.\n\nOnce the robots are weakened by the power of the storm, dismantle them utterly!", completion = "With their robotic minions dealt with, it is time for us to move on to bigger prey. Unfortunately, even now I feel the power of the storm waning from within you.\n\nNevertheless, it served its purpose, and I think that you're more than capable of taking the next step without it.", objectives = "While weakened by the Power of the Storm, destroy any 15 of the robotic units, except the mechagnomes, in the greater pools area surrounding the Fizzcrank Pumping Station.\n\nAfterward, return to Sage Earth and Sky at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11897] = { id = 11897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Sinkholes", description = "The Scourge are showing no sign of letting up, {name}.  It's those blasted sinkholes; they connect to tunnels all the way to Icecrown for all we know.  Giant undead worms burrow under the ground to create them.\n\nIf there's something years of mining has taught me it's that without support beams, tunnels will cave in easily after an explosion.\n\nTake these explosives and place them at the entrance to the sinkholes up on the ridge beyond the beach to the west.  Come back after you've collapsed them.", progress = "Did you succeed, {name}?  We need to slow down the Scourge or Valiance Keep will be overrun.", completion = "Excellent work, {name}.  Without you, Valiance Keep might've not held against the attackers.  Thanks to your help we'll live to fight another day.", objectives = "Sergeant Hammerhill wants you to use the Incendiary Explosives to collapse the sinkholes southwest and northwest of Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11898] = { id = 11898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through", description = "On the lowest tier of the Temple City, there is a gray altar bathed in light. Step into it to gain entry to the dread necropolis Naxxanar.\n\nBe cautious, {name}. Prince Valanar will certainly be defended by his personal retainers, who will give their lives to keep you from ascending to the top level of the necropolis.\n\nYou must find your way through the necropolis to the prince's seat. If you fail to defeat him, {name}, I fear my people will never know the safety Icemist offers.", completion = "With the prince defeated, the Scourge presence in Borean Tundra is broken. I have no illusions that they will stay away for long, which is why I must focus on preparing Durm to lead the villagers on their way to Icemist.\n\n<The chieftain shakes his head slowly.>\n\nFor all the disagreements I've had with Durm, I trust his judgment and his abilities. I cannot bring myself to abandon Taunka'le, so I will defend it until I am slain.", objectives = "Defeat Prince Valanar and his lieutenants, Vanthryn the Merciless and Luthion the Vile, then report to Chieftain Wintergale at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11899] = { id = 11899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Souls of the Decursed", description = "The mechagnomes in the pools to the west are a great mystery to us. They appeared not long after the gnomes disappeared from their pumping station and its environs.\n\nThey are an unnatural danger and must be dealt with.\n\nTake this soulcatcher and use it on the remains of the mechagnomes to capture their souls. When you return, we will set them free so that we might find out what happened.", completion = "Now we must free the souls that you have captured.", objectives = "Use The Greatmother's Soulcatcher to capture the souls of 10 Fizzcrank mechagnomes. Then, return to Greatmother Taiga at Taunka'le Village once you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11900] = { id = 11900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Meters", description = "I had hoped that the Nexus' impact was limited to this region. Recently though, reports have flooded in from all over Azeroth suggesting that geologic instability is growing exponentially!\n\nI need the Nexus monitored regularly as I work to develop a solution.\n\nI've placed sensitive instruments around Coldarra, disguised as Malygos' scrying orbs. One lies in the trench near the Nexus, and three are hidden in the structures around the valley's perimeter. Visit each and return to me with their readings.", completion = "This is worse than I expected.\n\nMalygos is channeling too much power to this place. If he's not stopped, Azeroth will be the next Outlands!\n\nFortunately, I believe that I've engineered a temporary solution....", objectives = "Archmage Berinand at the Transitus Shield has asked you to collect the readings from his instruments in Coldarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11901] = { id = 11901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Military? What Military?", description = "There's Scourge everywhere, {class}.  We've organized the farmers and miners into a militia, but this just won't cut it.\n\nThe one detachment of troops that Valiance Keep sent is defending the mine.  We haven't heard from them in days!\n\nIf you really wish to help us, why don't you go to the mine and see what's going on?  Maybe we can get them to send us some reinforcements.", completion = "Your stomach feels uneasy as you approach the grain.  The smell is nearly unbearable.", objectives = "Gerald Green in Farshire wants you to go into the mine to the north and find out what happened to the military detachment that was sent there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11902] = { id = 11902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pernicious Evidence", description = "The sacks of grain emanate the foul stench you've come to associate with the Plague.  This probably explains what happened to the footmen defending the mine.\n\nYou'd best bring word back to Gerald Green.", completion = "Those poor lads... they never had a chance!\n\nThis sure sounds like an inside job.  Probably a Cult of the Damned infiltrator.  Curse those madmen!", objectives = "Return to Gerald Green in Farshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11903] = { id = 11903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Time for Action", description = "Well, {name}.  With the last of our military in Farshire dead or worse, we can do but one thing: fight these Scourge ourselves.\n\nWe have deployed militia in what remains of Farshire.  Without your help, they've but little hope of winning.  Go and lend them a hand.  Me and the lads will watch this path.  We can't let the Scourge break through!", progress = "You giving those ghouls a good beating, I hope?", completion = "You've communicated with the Scourge in the only language they understand: violence and death.  Unfortunately they just keep coming!", objectives = "Gerald Green in Farshire wants you to kill 14 Plagued Scavengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11904] = { id = 11904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fruits of Our Labor", description = "The Scourge just keeps coming... but we can't give up!  Listen, {name}.  Inside that mine there's a cart with the last of the ore the Alliance is going to see on this side of the continent for a long time.\n\nThe problem is the cart release is locked.  When the military went in there, Captain Jacobs commandeered all the important equipment, including the cart release key.\n\nThe plague that affected the soldiers in the mine must also have affected Jacobs.  Get the key from him and salvage the ore.", progress = "The ore, {name}, is it safe?", completion = "I thank you, {name}.  This ore will be of vital importance to the Alliance in the times to come.  I'd like to think we've made a difference today.", objectives = "Go to the mine in Farshire, obtain the Cart Release Key from Captain Jacobs and use it to release the ore cart. Return to Gerald Green in Farshire when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11905] = { id = 11905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postponing the Inevitable", description = "Azeroth's ley lines are being redirected to the Nexus.\n\nThe influx of arcane energies is tearing a rift between dimensions.\n\nI cannot stop it, but I've discovered a way to slow it down.\n\nTake this and activate it near the forming rift.", progress = "Have you been to the rift?", completion = "Excellent work, {name}. The tremors have already begun to subside.\n\nWith any luck, your efforts have granted us sufficient time to find a way to thwart Malygos' efforts.", objectives = "Image of Warmage Kaitlyn in the Nexus wants you to use the Interdimensional Refabricator near the rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11906] = { id = 11906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Up the Pools", description = "<A single tear rolls down the face of Iron Eyes.>\n\nI have heard that you are heading back into the pools to the west. I have something for you to do while you are out there, {race}.\n\nThe gnomes, who care nothing for the land, have polluted it with their machinery. I want you to pick up any spare parts that you come across.\n\nReturn them to me here. I will see to it that they are properly disposed of before we leave this place for good.", progress = "If we do not take care of the land, she will not suffer us to live for long.", completion = "It is the taunka way to leave the land pristine before we move on.\n\nWe will be traveling to our capital, Icemist, very soon. You have helped by allowing us to depart that much more quickly.\n\nThank you.", objectives = "Collect 15 Fizzcrank Spare Parts and deliver them to Iron Eyes at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11907] = { id = 11907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sub-Chieftains", description = "It is known that Gearmaster Mechazod has four sub-chieftains that manage the robots in the pools.\n\nWe must put an end to them!\n\nOur longrunners and snow trackers say that if you were to turn the valves at the west point, north point, mid point and south point stations, each of his sub-chieftains would come quickly to prevent you from fouling their operations.\n\nThe stations are centered on the spinning lights in the pools surrounding the pumping station.\n\nHurry, {name}!", completion = "Thank you, {name}.\n\nWith these odd creatures destroyed, dealing with the rest of the pools should now be a simple matter.\n\nWe owe you a debt of gratitude.", objectives = "Defeat Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Sage Earth and Sky at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11908] = { id = 11908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reference Material", description = "I was in charge of the harvest golems - an important job until the Scourge destroyed most of our farmlands.  I've an idea that would make the golems useful again, however.\n\nI think I can rewire the harvest collectors so they'll give us a hand fighting the Scourge.\n\nI'm not an expert at this just yet, so I'm going to need my manual.  The problem is, I left it at the workshop... which happens to be that burning building next to the mine.  Think you could go salvage it?", progress = "Did you get my book back?", completion = "Excellent!  The information I need should be in here.", objectives = "Jeremiah Hawning wants you to retrieve the book \"Fields, Factories and Workshops\" from the burning building next to the mine in Farshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11909] = { id = 11909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeat the Gearmaster", description = "Clearly this Gearmaster Mechazod creature is not in his right mind. If his offer of a cure and immortality means all of us becoming robotic slaves then he must be stopped!\n\nThe winds that guide me whisper that he's atop the pumping station out in the middle of the pools to the west.\n\nMost likely, he'll be found in the command hut on top of the structure. Go inside and research his works.\n\n{name}, you must confront Mechazod if we are to survive!", progress = "Is it over then? Has the threat of Gearmaster Mechazod been eliminated?", completion = "<The greatmother breathes a heavy sigh of relief.>\n\nIt is done then... you have saved us! If you hadn't stopped him here, then who knows how far this mistake of the gnomes would have spread?\n\nWith the threats from the blue dragons and the Nexus War, not to mention the Lich King, the last thing we need is a mad creation of the Titans running loose!\n\nThank you, {name}.", objectives = "Research the Gearmaster's Manual and return Mechazod's Head to Greatmother Taiga at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11910] = { id = 11910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Ancients", description = "It's become clear that the instability in the region has had an effect on its indigenous creatures.\n\nI've taken a particular interest in the Glacial Ancients and their recent adaptations. I suspect that their transformation into these 'Magic-bound' Ancients may hold clues to our predicament here.\n\nFor my studies, I'll need samples from both. Do hurry....", progress = "Have you collected the samples I requested?", completion = "Yes, yes. These shall do nicely.\n\nThank you, {race}.", objectives = "Archmage Berinand in the Transitus Shield wants you to collect 3 Glacial Splinters and 3 Magic-Bound Splinters from the Ancients in Coldarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11911] = { id = 11911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quickening", description = "I've learned more in my short time here than in decades of studies.\n\nThe ancients here are being exposed to incredible levels of arcane energy. It's literally transforming them into something...\n\nI'm confident that there's a final stage in their metamorphosis. Find me some evidence of their final state.", progress = "The crystalline ancients... Do they exist?", completion = "Fascinating!\n\nAnd they're aggressive too, you say. That would suggest that some intelligence is behind this manipulation.\n\nIt may not be natural at all....", objectives = "Image of Warmage Kaitlyn in the Nexus wants you to collect 5 Arcane Splinters from Crystalline Protectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11912] = { id = 11912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuts for Berries", description = "Oh! What a relief it is to see a fresh face. I was beginning to feel we had been forsaken.\n\nOur supply lines were cut off days ago, and things have been looking - well, bleak. To be honest, this was a suicide mission to begin with if you ask me.\n\nMaybe I'm simply not cut out for all of this violence - to say nothing of the bitter cold! I'd much rather be back in Dalaran studying ancient texts.\n\nTo the point, our food supply is nearly spent. Please, gather what you can and bring it to me.", progress = "Have you been able to find any food?", completion = "Well, it's not much, but it should keep us alive for another day.\n\nI believe you'll find this to be a fair price for your efforts.", objectives = "Librarian Serrah in the Transitus Shield wants you to gather 10 Frostberries from the Frostberry Bushes in Coldarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11913] = { id = 11913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take No Chances", description = "I heard what you told Gerald and I don't like it one bit.  If cultists managed to poison the grain in the mines with their foul plague, they could've easily done the same with the grain outside.\n\nWe don't have time to sort the good grain from the bad.  We must act quickly and burn it all.\n\nTake this torch and set fire to any sacks of grain you find out here.  It would be a tragedy if we survived this attack only to succumb to the plague afterwards.", progress = "Have you done what I asked of you, {name}?", completion = "I thank you, {name}.  I would hate to see survivors of the attack on Farshire stumble upon plagued grain.", objectives = "Wendy Darren wants you to use Wendy's Torch to burn 8 sacks of Farshire Grain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11914] = { id = 11914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep the Secret Safe", description = "Our existence here depends entirely upon staying hidden. Should the shield fail, even for a moment, Malygos' minions would have us.\n\nOne of my responsibilities is to rejuvenate the warmages' mana levels so their focus doesn't falter. With our supply lines lost, I've been forced to improvise.\n\nI could use your help, {name}.\n\nVery near the Nexus, Arcane Serpents feast on the abundant magical energies. Once defeated, they will yield a mana essence that I can make use of.", progress = "Do you have the mana essences I asked for?", completion = "Your service to Dalaran will not go unnoticed, {race}.\n\nI hope you find this payment sufficient.", objectives = "Librarian Serrah in the Transitus Shield needs you to kill Arcane Serpents near the Nexus and collect 5 Nexus Mana Essences from them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11915] = { id = 11915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Flame Eater at any Horde capital. They should be able to help you.", completion = "Greetings. You've come to learn some new ways to handle fire?", objectives = "Speak to a Master Flame Eater in any Horde capital.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11916] = { id = 11916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Champion", description = "You have faced all challenges that have been set before you and squashed them beneath your boot heel. It is because of you, {name}, that the Horde is now firmly entrenched in Northrend.\n\nBut our work has only just begun. We must march to Icecrown and we must tear down its walls!\n\nYour next assignment begins to the east, at Taunka'le Village. Our taunka allies are in dire straits and require aid. Secure transport from the stable master, Durkot Wolfbrother, and seek out Chieftain Wintergale at Taunka'le.", completion = "I fear that you may be too late, champion. Many of my brothers and sisters have already abandoned Taunka'le, seeking shelter in the Dragonblight, far to the east.\n\nThere is much work left to be done here and few willing to lend us their strength...", objectives = "Seek out Chieftain Wintergale at Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11917] = { id = 11917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nReturn to the camp on the Zoram Strand with the large ice stones. They use them to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", objectives = "Slay the Frostwave Lieutenant summoned from the Ice Stone located on Zoram Strand in Ashenvale, then return to the Earthen Ring Elder in a capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11918] = { id = 11918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Training", description = "This is war, mortal, and we are the tip of the spear.\n\nYour little spats over land or currency pale in comparison to this conflict. We face the aspect Malygos and his entire blue dragonflight. All you need to know is that if he is victorious, this world shall be no more.\n\nWe are but few here, and we fly against many. Our deaths are all but a certainty, and our ultimate success lies in merely delaying our enemy.\n\nGo now. Busy yourself while I decide what to do with you.", progress = "Have you acquainted yourself with our enemy, {class}?", completion = "Alright, {class}, now that you've become familiar with the enemy it's time for you to get to work.", objectives = "Raelorasz at the Transitus Shield wants you to slay 10 Coldarra Spellweavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11919] = { id = 11919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drake Hunt", description = "The blues have begun to cover their drakes in mysterious runes. I must discover their significance.\n\n<Raelorasz pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.\n\nTheir hatchlings feed around the northwest edge of the valley.", progress = "Have you managed to capture one of the Nexus Drakes?", completion = "The fate of these young drakes need not burden your conscience, {race}. Malygos alone is accountable for this.\n\nI am working ceaselessly to discover the secrets of these runes. We shall take no more lives than we must.", objectives = "Raelorasz wants you to use Raelorasz's Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11920] = { id = 11920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultists Among Us", description = "This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.\n\nPerhaps he is to be found above deck.", completion = "Cultists?  Below deck?  I ought to have my whole crew flogged!\n\nListen... why don't we have Admiral Cantlebree take care of this... situation?", objectives = "Speak to Captain \"Lefty\" Lugsail above the Stormbreaker in Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11921] = { id = 11921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!", objectives = "Win the torch tossing game, then speak with the Master Fire Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11922] = { id = 11922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lesson.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", objectives = "Win the torch tossing game, then speak with the Master Flame Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11923] = { id = 11923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four then come back to me.\n\nCareful! They're dangerous if they hit the ground! Good luck!", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!", objectives = "Catch 4 torches in a row, then speak with the Master Flame Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11924] = { id = 11924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "How's that arm doing, {name}?  You looked great out there.  A real juggling master!", objectives = "Catch 10 torches then speak with the Master Fire Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11925] = { id = 11925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "How's that arm doing, {name}?  You looked great out there.  A real juggling master!", objectives = "Catch 10 torches then speak with the Master Flame Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11926] = { id = 11926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!", objectives = "Win the torch tossing game, then speak with the Master Flame Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11927] = { id = 11927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word on the Street", description = "Hey, {name}.  There's a girl in the inn that's asking about you.  Her name's Leryssa.\n\nI don't think she knows you, but she said she needed your help.  She sounded really desperate.", completion = "Thank you for coming to see me.  I didn't know who else to contact.", objectives = "Find Leryssa at the inn in Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11928] = { id = 11928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farshire", description = "My lads should be able to take it from here, {name}.  Valiance Keep is built to take a beating far worse than this.  I worry about our farmlands and mine in Farshire, however.\n\nWe sent a full detachment to protect our mining operations right before the invasion - they should be able to defend the civilians.\n\nGerald Green's in charge of the villagers there. There's a passage out of the northern wall out of Valiance Keep; it'll take you straight to him.  See what you can do to help them.", completion = "You're here to help?  You're just in time then!", objectives = "Travel to Farshire in Borean Tundra and speak to Gerald Green.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11929] = { id = 11929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Taunka'le Village", description = "We are lost, {name}. This place has been our home for many generations, but it is no longer safe. There remains only death... Death and a memory of what used to be.\n\nI have called for the evacuation of Taunka'le. All remaining taunka must leave at once and make their way to our capital city, Icemist, located in the Dragonblight.\n\n<Wintergale points east.>\n\nYou must help get my people to safety, {name}. Mother Tauranook awaits you at the village gates. Hurry! The Scourge closes in from all sides!", completion = "<Mother Tauranook wipes her tears away.>\n\nThere was once a time when I could walk across this tundra and the snow would fill my view for as far as I could see.\n\nBut the snow has left us - signaling that our time here has come to an end. We leave behind Taunka'le Village and the Borean Tundra with many happy memories...\n\n<Mother Tauranook whimpers.>\n\nPerhaps the future will welcome our return - along with the snow.", objectives = "Speak to Mother Tauranook outside the gates of Taunka'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11930] = { id = 11930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across Transborea", description = "The path across Transborea, to the east, is the only way to reach the Dragonblight. Many perils await you as you make your journey across the tundra. Beware the Scourge and its influence upon the beasts of the land. Rumors have started to spread about our very own taunka brothers and sisters rising from the dead and attacking caravans on their way to the Dragonblight! Defend your caravan and get the evacuees to safety!\n\nWartook Iceborn waits for you across the bridge leading into the Dragonblight.", progress = "It's gone. It's all gone.", completion = "<Wartook looks upon you grimly.>\n\nIcemist is no more...", objectives = "Escort the Taunka'le Evacuees across Transborea to Wartook Iceborn on the border of the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11931] = { id = 11931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking the Code", description = "I sense a distinct peculiarity in the drakes here but the meaning of the runes that cover their bodies still eludes me.\n\nWithout a codex, it will take more time than we can afford for me to interpret them.\n\nNot far from here is a Kirin Tor traitor, Caleras, who is likely to have a copy of the tome I require. His underlings hold the runes I will need for my translation.\n\nHurry, mortal. Malygos gains strength with every passing moment.", progress = "Hurry, mortal.\n\nMalygos gains strength with every passing moment.", completion = "You have done well, {race}.\n\nLet us hope for a clue that we can use against Malygos.", objectives = "Raelorasz at the Transitus Shield wants you to get the Azure Codex from Inquisitor Caleras and collect 3 Shimmering Runes from his Coldarra Spellbinders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11932] = { id = 11932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cowards and Fools", description = "Listen, {name}.  No offense, but the operation they put Thassarian in charge of was pure suicide.\n\nA handful of our men were to launch an attack on the biggest Scourge presence in the area.  Call me crazy, but storming a Scourge ziggurat outside a plagued Nerubian city with a dozen men ain't my idea of fun.\n\nIf you're still interested in finding Thassarian, we were supposed to arrange for passage east with a tuskarr by the name of Ataika in Kaskala to the northeast.  Good luck with your fool's errand.", completion = "I remember the man you speak of.  He bore the marks of Karkut.\n\nMay Karkut protect our fallen.", objectives = "Speak to Ataika in Kaskala, northeast of Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11933] = { id = 11933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Exodar's Flame", description = "This flame, stolen from the heart of the Exodar itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "This fire seems new... Yet, you say it came from the Exodar? Fascinating! To make your way into that ship...  Of course, I'll pay you for this. If you find anything else like this, be sure to speak with me again.", objectives = "Return the Flame of the Exodar to the Festival Talespinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11935] = { id = 11935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Silvermoon's Flame", description = "This flame, stolen from Silvermoon, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "What a glorious fire! You received this from Silvermoon, you say? Unbelievable! With the flames of all four cities, who knows what we could accomplish?", objectives = "Return the Flame of Silvermoon to the Festival Loremaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11936] = { id = 11936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatching a Plan", description = "Our goals here are simple. We are to remain hidden from Malygos, observe his brood, and thwart his efforts wherever possible. To that end, I have a task for you.\n\nThe blues are laying their eggs at the base of the Nexus. Exposure to so much arcane energy will surely make them hatch sooner, and there's no telling what effect it will have on their spawn.\n\nI don't intend to find out. Slay the local wyrmkin and use their frozen axes to break the eggs.", progress = "Have you destroyed the blues' eggs, {class}?", completion = "It pains me to order the destruction of dragon eggs, enemy or no.\n\nMay the ends of this war justify the means....", objectives = "Raelorasz at the Transitus Shield wants you to kill Coldarra Wyrmkin and use their frozen axes to break 5 blue dragon eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11937] = { id = 11937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - all torch return quests are complete" }
quests[11938] = { id = 11938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buying Some Time", description = "Now that we have this phylactery, I shouldn't have any problems getting the information I need.  It won't take long for the Scourge in the Temple City to notice something's up, however.\n\nI won't be able to fend off a full scale attack here.  Or maybe I would... but I'd rather not find out.\n\nI want you to head down there and inflict some casualties.  Hopefully they'll be distracted long enough for these two to spill their guts... figuratively, of course.  Take Lurid with you, he might be of aid.", progress = "Is it done?", completion = "That should buy us some time.  Isidorus has been cooperative, but I really needed that alone time with the lich.", objectives = "Thassarian at the Wailing Ziggurat in Borean Tundra wants you to inflict 20 casualties against the Scourge inside the Temple City of En'kilah. Use Lurid's Bones if you need assistance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11939] = { id = 11939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "?????" }
quests[11940] = { id = 11940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drake Hunt", description = "I need more drake hatchlings to continue researching the runes covering their bodies.\n\nThey can be found around the northwest edge of the valley....\n\n<Raelorasz pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.", completion = "The fate of these young drakes need not burden your conscience, {race}. Malygos alone is accountable for this.\n\nI am working ceaselessly to discover the secrets of these runes.\n\nRest assured, we shall take no more lives than we must.", objectives = "Raelorasz wants you to use the Blood-tipped Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11941] = { id = 11941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puzzling...", description = "Something about this scrap of metal prevents you from casting it aside.\n\nPerhaps Raelorasz might be able to shed some light on its purpose.", progress = "What have you found, {class}?", completion = "It was wise of you to bring this to me, {name}.\n\n\n\nIf you truly desire to contribute to our efforts, no matter the risk, I shall share with you its meaning.", objectives = "Bring the Scintillating Fragment to Raelorasz at the Transitus Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11942] = { id = 11942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Power", description = "The lich has spoken, {name}.  The high priests of En'kilah hold the secret to entering Naxxanar.\n\nGo to the Spire of Blood, the Spire of Pain and the Spire of Decay and slay each of the priests.\n\nReturn once you've obtained the three scrolls.", progress = "Taking your time, are you?  I don't know how much longer I can keep this lich restrained.", completion = "Excellent work, {name}.  Now for one last bit of information.", objectives = "Thassarian at the Wailing Ziggurat wants you to go to the Temple City of En'kilah and retrieve High Priest Talet-Kha's Scroll from the Spire of Pain, High Priest Naferset's Scroll from the Spire of Decay and High Priest Andorath's Scroll at the Spire of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11943] = { id = 11943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cell", description = "You've discovered a fragment of a special prison, {name}.\n\nMalygos' minions use similar prisons to hold their captured mages and other arcane entities, but this prison was constructed to hold something... stronger.\n\nIn hopes that the enemy of our enemy will prove to be a friend, you must search for the prison's remaining fragments.\n\nThey are likely to be in the possession of Malygos' most trusted underlings.", progress = "Have you discovered any other pieces to the prison?", completion = "<The pieces you've collected begin to glow brightly in Raelorasz' hands.>\n\nIt is done.\n\nI sense a strong presence within this prison. Let us hope it proves to be an ally.", objectives = "Raelorasz at the Transitus Shield wants you to obtain the Prison Casing from General Cerulean and the Energy Core from Warbringer Goredrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11944] = { id = 11944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrounded!", description = "Our situation is nearly hopeless.  We were ordered to take the Wailing Ziggurat with a handful of men.\n\nWe'll be lucky if we can hold this position against the Scourge.  We're outnumbered, injured and have no escape route.\n\nIf you can take some of the pressure off of us, we might be able to solidify our position.  Kill some of the undead circling the structure - we'll hold off their advance.", completion = "That should buy us some time, {name}.  We'll hope against hope for reinforcements from Valiance Keep.", objectives = "Corporal Venn at Death's Stand wants you to slay 7 Ziggurat Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11945] = { id = 11945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing for the Worst", description = "Dark times are upon us.  Karkut's spirit walks the earth and gathers the spirits of dead tuskarr.\n\nThe sons of the mist have taken many of our brethren.  Soon dear Kaskala will be reduced to ashes.\n\nThere is hope yet.  Not for us perhaps, but we've sent our families to Unu'pe.  We fight here so there may be a future for them.\n\nThey will need supplies or they will starve.  There's not enough food in Unu'pe.  Salvage any supplies before it's too late for our families.", progress = "Have you succeeded, {name}?  Our relatives in Unu'pe are depending on your efforts.", completion = "I thank you, {name}.  These supplies will feed our cousins and children.  Even if Kaskala falls, our tribes must carry on.", objectives = "Utaik wants you to gather 8 Kaskala Supplies in Kaskala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11946] = { id = 11946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keristrasza", description = "I am... free?\n\nI was destined to spend an eternity roaming an empty abyss, and now am saved? You cannot fathom my gratitude, mortal.\n\nWhen I refused to bend to his will Malygos bound me to that prison, then shattered it and scattered the pieces. Should I live one hundred of your lifetimes, I shall not forget this kindness.\n\nPerhaps, in time, I will find ways to repay you. For now, though, we must focus our attention on Malygos. I am weak, and there is much to be done.\n\nI need your help, {name}.", completion = "We cannot wait for me to regain my strength.\n\nI must rely on you to make our preparations....", objectives = "Use the Augmented Arcane Prison to summon and speak to Keristrasza.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11947] = { id = 11947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nThere is a camp located in the shadow of Ethel Rethor within northwestern Desolace. There, they use ice stones to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", objectives = "Slay the Hailstone Lieutenant summoned from the Ice Stone located at Ethel Rethor in Desolace, then return to the Earthen Ring Elder in a capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11948] = { id = 11948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nNeptulon has long had a base of operations on an island in western Stranglethorn. There, the Twilight Cult has set up ice stones to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", objectives = "Slay the Chillwind Lieutenant summoned from the Ice Stone located on the water elemental's island in western Stranglethorn Vale, then return to the Earthen Ring Elder in a capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11949] = { id = 11949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Without a Fight!", description = "Kaskala is a sacred place for us, {race}.  Our ancestors were guided here by the spirit of Tayutka herself.\n\nNow these foul creatures attack us from the mists without any provocation.\n\nWe will show them that our spears are not merely for whaling.  Fight alongside us, friend.  Perhaps my people might repay you some time in the future.", completion = "I thank you, {name}.  I will be deeply in your debt if we ever make it out of here alive.", objectives = "Ataika wants you to slay 12 Kvaldir Raiders in Kaskala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11950] = { id = 11950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muahit's Wisdom", description = "Listen, {name}.  Warriors like me are replaceable.  If I fall, my brothers and cousins will pick up my spear and fight.\n\nMy people cannot survive without wise elders.  Stubborn Muahit, our most venerable shaman, refuses to leave the altar to Tayutka in the central island.  We would suffer a significant loss if he was slain by these monsters.\n\nYou are an outsider, maybe he'll listen to you.  Show him reason... ask him to flee to the safety of Unu'pe before it's too late.", completion = "Ataika sent you, didn't he?  I am not to be swayed.\n\nAll is not lost.  The spirits are still with us.", objectives = "Find Elder Muahit in Kaskala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11951] = { id = 11951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bait and Switch", description = "During my captivity I was able to learn much about Malygos. Fate now allows us to use this knowledge against him.\n\nThere is a great blue dragon, Saragosa, who circles high above the Nexus. She serves both as the aspect's guardian and as his consort. If any serious threats arise, she alerts her master of the danger.\n\nI suffered greatly at the hand of Saragosa during my captivity, and now her time to die has come. First, however, we must fashion the perfect bait....", progress = "Have you gathered the mana shards I require?", completion = "Thank you, {name}.\n\nI am drained from the effects of my confinement and my strength is returning ever so slowly.\n\nI shall use the power from these crystals wisely. They are a byproduct of Malygos' malevolent schemes. With luck, they will play a part in his undoing.", objectives = "Keristrasza has asked you to collect 10 Crystalized Mana Shards from around Coldarra.\n\nIf you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11952] = { id = 11952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nFirewatch Ridge in Searing Gorge is an established bastion of Twilight Cult activity. Recently, they have been using ice stones in the cave to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", objectives = "Slay the Frigid Lieutenant summoned from the Ice Stone located in the cave underneath Firewatch Ridge in the northwest of Searing Gorge, then return to the Earthen Ring Elder in a capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11953] = { id = 11953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nSilithus is the Azerothian base of the Twilight Cult. In the north, they have been using new ice stones to communicate with the Tidehunter's realm. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", objectives = "Slay the Glacial Lieutenant summoned from the Ice Stone located at Twilight's Run in northern Silithus, then return to the Earthen Ring Elder in a capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11954] = { id = 11954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nIn order to ensure Ahune's success, the cult has established a base near the Dark Portal itself in Draenor. They use ice stones to coordinate the frost lord's arrival. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's templar protectors and destroy it. Perhaps this forestalling action will be enough...", progress = "You have returned victorious?", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", objectives = "Slay the Glacial Templar summoned from the Ice Stone located near the Dark Portal in Hellfire Peninsula, then return to the Earthen Ring Elder in a capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11955] = { id = 11955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune, the Frost Lord", description = "I believe you are strong enough for the ultimate task set before us.\n\nWe cannot allow the plot between the Twilight Cult and the naga heretics of Neptulon to come to fruition. For the sake of Azeroth and all life upon it, we must act. Our path is clear. You must journey to the Slave Pens deep within Coilfang Reservoir and meet with our shaman there. Go, and quickly!", sourceObjective = "Travel to the Slave Pens in Coilfang Reservoir within Zangarmarsh and speak with Numa Cloudsister.", sourceObjectiveStatus = "unverified-source-field" }
quests[11956] = { id = 11956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Phylactery", description = "No time for small talk, {name}.  I was sent on what was to be a suicide mission to take this ziggurat.  I've accomplished my duty as a soldier, now is the time to get some answers.\n\nThis lich has knowledge I seek, yet I cannot inflict pain to his physical body to obtain that knowledge.\n\nThe lich stored his soul in a phylactery, and while it remains hidden, I won't be able to pry the information from him.\n\nReturn to the camp and take my horse, Dusk, she will lead you to the phylactery.  Bring it to me.", progress = "You're back, {name}.  Did you get the phylactery?", completion = "Just in time, {name}.  Pinning down a lich is not as easy as it looks.", objectives = "Go to Death's Stand and ride Dusk to the location of Tanathal's Phylactery. Obtain it and bring it back to Thassarian inside the Wailing Ziggurat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11957] = { id = 11957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saragosa's End", description = "Using the mana crystals you provided, I have created this Power Focus.\n\nSaragosa is a glutton. She will be unable to resist its lure. Inside it lie magics that will greatly diminish her power. Let us hope she does not see through my ruse....\n\nPrepare yourself, {name}, and speak to me again when you are ready to face Saragosa.", progress = "Saragosa must not be allowed to live!", completion = "This world is a better place now that Saragosa is no more, but our work is not yet finished.\n\nThe time has come to strike at Malygos himself!", objectives = "Keristrasza wants you to use the Power Focus to lure Saragosa, and then defeat her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11958] = { id = 11958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Nothing Go To Waste", description = "The wolvar have always been our natural enemies. But the incursion of your peoples into the Great Dragonblight has forced them into a small space upon the glade to the north.\n\nCombined with the land's upheaval this morning, they have become even more aggressive than ever before. They have made several raids upon our goods... things that we'll need if we are to survive the trek from our home here.\n\nAs a sign of good faith and friendship, retrieve our goods from the Snowfall Glade wolvar.", progress = "The natural balance has been tipped over and over of late.\n\nI hope that you will be able to help us survive the upheaval of our way of life.", completion = "I will not say that I am pleased to ask you to do such things on our behalf. It is all we can do to prepare quickly for our departure, though we know not yet where we go.\n\nMy sorcerers tell me that you are here to save the land from He Who Walks in Shadow.\n\nI trust that you will save the peoples of the land as well.", objectives = "Retrieve 6 Stolen Moa'ki Goods from the wolvar. Return them to Elder Ko'nani at Moa'ki Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11959] = { id = 11959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay Loguhn", description = "Already it goes from bad to worse. There is only one course to take... regrettably, Loguhn must die!\n\nHe's the alpha male of the Snowfall Glade tribe and one mean wolvar. But it's the only way to get a short break from their attacks and stealing forays.\n\nYou will find the \"Render of Flesh\" in front of his hovel upon the northern rise of the glade. It's larger than the others and hard to miss. Kill him and smear his blood upon yourself, both to show your dominance and respect.", completion = "Loguhn's honorable sacrifice at your hands is exactly what my people need. Now we will make the most of the wolvar in-fighting for his place.\n\nIt will have to be enough.", objectives = "Smear the Blood of Loguhn upon yourself and then return to Elder Ko'nani at Moa'ki Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11960] = { id = 11960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planning for the Future", description = "We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain.\n\nThe Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance.\n\nIf Elder Ko'nani hasn't asked you already, he will ask you to deal with them.  While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.", progress = "How many pups could you have possibly saved in so short a time?", completion = "Well, I guess you saved plenty of them. Thank you, {race}.\n\nNow the wolvar will have a chance of surviving along with us. If we survive at all, that is.\n\nDo you think that you could return tomorrow so that we can save more of the pups?", objectives = "Collect 12 Snowfall Glade Pups. Deliver them to Trapper Mau'i at Moa'ki Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11961] = { id = 11961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits Watch Over Us", description = "Powerful spirits watch over my tribe -- Kaskala will not be lost.\n\nIssliruk will give us courage, Tayutka will make sure our survivors always have food and shelter and Karkut will watch over the fallen so they do not lose their way.\n\nIssliruk's guidance is the one we need the most right now.  I asked my nephew, Iruk, to bring me Issliruk's totem, but the Kvaldir's spears struck him down and his body fell into the waters to the north.  Bring me the totem, {name}.  Don't let my nephew's death be in vain.", progress = "The totem, {race}.  Do you have it?", completion = "Can you feel Issliruk's presence, {name}?  He does not want his children to perish at the hand of the mist-walkers.", objectives = "Elder Muahit at Njord's Breath Bay wants you to find Iruk's corpse in the water and retrieve Issliruk's totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11962] = { id = 11962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Delivery", description = "That's it then.  With the last of the ore you salvaged we now have enough to send to Valiance Keep.\n\nIf Farshire is wiped off the face of Azeroth, then at least let us be remembered as the first ones to defend our land and the last ones to give up.\n\nTake this ore to Hilda Stoneforge - she is a good friend of mine.  Tell her to make some good weapons with this ore.  We'll need plenty of them in the days to come.", progress = "What do you have there?", completion = "Ore from Farshire?  We weren't scheduled for a shipment just yet.  Is something wrong?", objectives = "Deliver the Crate of Farshire Ore to Hilda Stoneforge in Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11963] = { id = 11963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons for Farshire", description = "Farshire is overrun and all that Gerald can think of is to get me my ore shipment?  I swear that man has as much heart as any of our soldiers on the frontlines.\n\nWe cannot let the civilians lose their lands if they're willing to fight for them.  We might not have the troops to spare, but we can send them weapons.\n\nThese were earmarked for new recruits, but I'll be able to cover those with the ore you've brought me.  Send word to Gerald that weapons are on the way.", completion = "Hilda's sending us weapons?  That's excellent news, {name}.  I was about ready to tell the lads to pack things up.", objectives = "Return to Gerald Green in Farshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11964] = { id = 11964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incense for the Summer Scorchlings", description = "Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any summer scorchling.  Appease the little fire spirit, and it may reward you.", progress = "A fiery salutations to you, honored {class}.  Welcome to this hallowed ground of the Midsummer Fire Festival.", completion = "Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!\n\nTake this blossom, {name}.  Take it, and leave me be... I must attend to this precious fuel...", objectives = "The Festival Loremaster wants you to take Summer Incense to a Summer Scorchling outside any Alliance settlement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11965] = { id = 11965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms!", description = "Farshire has a fighting chance now, {name}.  That's all we could've asked for and you've made it possible.\n\nAll we need now is a rallying point.  I'll have my men deliver the weapons to our town hall.  Go and ring the town hall bell so any survivors know to rally there.\n\nIt's time to show the Scourge what we're made of.", completion = "Thanks once again for aiding us, {name}.  The people of Farshire will always remember you.", objectives = "Go to the town hall building in Farshire and ring the bell inside of it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11966] = { id = 11966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incense for the Festival Scorchlings", description = "Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any festival scorchling.  Appease the little fire spirit, and it may reward you.", progress = "A fiery salutations to you, honored {class}.  Welcome to this hallowed ground of the Midsummer Fire Festival.", completion = "Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!\n\nTake this blossom, {name}.  Take it, and leave me be... I must attend to this precious fuel...", objectives = "The Festival Talespinner wants you to take Summer Incense to a Festival Scorchling outside any Horde settlement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11967] = { id = 11967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mustering the Reds", description = "Malygos is certainly aware that something is amiss.\n\nI know him. His focus is fragmented. I am confident that I can lure him from the safety of his realm when he learns what has become of his precious Saragosa.\n\nTake me to Raelorasz at once, {name}. He must rouse every dragon he commands to face Malygos.", progress = "You have news for me, {name}?", completion = "Word of Keristrasza's rescue has reached my ears. You are to be commended.\n\nI am eager to speak with her again.", objectives = "Keristrasza has asked you to bring her to Raelorasz at the Transitus Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11968] = { id = 11968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tides Turn", description = "The spirits have heard our cry for help, {name}.  It's a sign that Kaskala might yet be saved.\n\nTake advantage of the confusion the weather has created and slay the Kvaldir leader.  Your actions will sway the battle in our favor, I am sure of it.", progress = "Have you done what I asked of you, {name}?", completion = "You've done us a great favor, {race}.  The fight is not yet won, but my people now have a chance.", objectives = "Elder Muahit wants you to kill Heigarr the Horrible in Njord's Breath Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11969] = { id = 11969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Springing the Trap", description = "We owe this opportunity in great part to your efforts, {name}.\n\nIt is only fitting that you initiate the attack on Malygos.\n\nTake this spark and use it to light the signal fire northwest of the Nexus. Keristrasza will direct you from there.", progress = "Did you meet with Keristrasza?", completion = "We have dealt a blow to Malygos, but it has come at a high price.", objectives = "Raelorasz wants you to use Raelorasz' Spark at the signal fire in Coldarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
